{
  "name": "pilcrow",
  "productName": "Pilcrow",
  "version": "3.0.4",
  "private": true,
  "description": "Desktop workbench for Claude Code on Linux",
  "type": "module",
  "main": "electron/main.cjs",
  "bin": {
    "pilcrow": "bin/pilcrow"
  },
  "scripts": {
    "build": "vite build",
    "dev": "vite build --watch",
    "start": "bin/pilcrow",
    "server": "node server/main.js --shell=none",
    "mock": "node test/mock/mock-server.mjs 5300",
    "check": "tsc --noEmit -p tsconfig.json",
    "check:server": "tsc --noEmit -p tsconfig.server.json",
    "lint": "eslint web/src test server electron scripts/css-overlap.mjs && node scripts/css-overlap.mjs",
    "test": "npm run check && npm run check:server && npm run lint && npm run test:unit && npm run test:e2e && npm run test:ux && npm run test:perf && npm run test:webkit",
    "test:unit": "vitest run",
    "test:e2e": "node test/e2e/run.mjs",
    "test:webkit": "node test/webkit/run.mjs",
    "test:perf": "node test/e2e/perf.mjs",
    "test:ux": "node test/e2e/ux.mjs",
    "release": "node scripts/release.mjs",
    "installers": "python scripts/make-installers.py --verify"
  },
  "engines": {
    "node": ">=20"
  },
  "dependencies": {
    "@anthropic-ai/claude-agent-sdk": "0.3.300",
    "ws": "8.22.0",
    "zod": "^4.0.0"
  },
  "optionalDependencies": {
    "electron": "44.10.1"
  },
