            self.set_chrome(head_h=0, pad_top=0, pad_bottom=0)
            return self.h
        self.set_chrome(head_h=HEAD_H + self.peek_height(width, m), pad_top=4, pad_bottom=6)
        return self.h

    def estimate(self, width: int, m: Measurer) -> int:
        if self.hidden and self.head_h:
