"""Design tokens and the application stylesheet.

A port of web/src/styles/tokens.css: warm neutrals in the key of Claude's own apps, charcoal and
bone rather than blue-grey, with Claude's orange as the single accent. Orange is reserved for the
primary action, the send button, attention ("needs you") and focus; lilac marks reasoning and
nothing else.

Widgets never carry literal colours. They paint with ``tokens()``, or take their colours from a
palette: the application palette carries the theme (``palette()`` maps the tokens onto Qt's roles),
and ``tint()`` gives one widget other roles from the tokens (a fainter text, a chrome background),
re-applied whenever the theme changes. The application stylesheet (``stylesheet()``) is static: it
sets geometry and fonts and names colours only as ``palette(role)``, so a theme switch is a palette
change and a repaint, not a re-parse of every widget's style.
"""

from __future__ import annotations

import math
import os
from dataclasses import dataclass
from typing import Callable, Dict, Optional, Tuple, Union

from PySide6.QtCore import QEasingCurve, QObject, QPointF, QStandardPaths, Signal
from PySide6.QtGui import QColor, QFont, QFontDatabase, QPalette
from PySide6.QtWidgets import (
    QAbstractItemView,
    QAbstractSpinBox,
    QApplication,
    QComboBox,
    QLineEdit,
    QPlainTextEdit,
    QScrollBar,
    QTextEdit,
    QWidget,
)

# ---------------------------------------------------------------- type scale, radii, spacing

FS_MICRO = 11
FS_SMALL = 12
FS_UI = 13
FS_BODY = 14.5
FS_H = 15
FS_TITLE = 17
FS_DISPLAY = 22
MONO_SIZE = 12.5

R1, R2, R3, R4, R5 = 4, 6, 10, 16, 999
SP1, SP2, SP3, SP4, SP5, SP6 = 4, 8, 12, 16, 24, 32
HEADER_H = 48
COL = 700  # the conversation column: ~80 characters at 14.5px

T_FAST, T_MED, T_PANEL, T_SLOW, T_EXIT = 120, 180, 240, 300, 140


@dataclass(frozen=True)
class Tokens:
    """One theme's colours. Names follow tokens.css (``--text-2`` → ``text_2``)."""

    name: str
    dark: bool
    canvas: str
    chrome: str
    raised: str
    raised_2: str
    inset: str
    hair: str
    hair_2: str
    hair_3: str
    fill_1: str
    fill_2: str
    fill_3: str
    text: str
    text_2: str
    text_3: str
    text_4: str
    accent: str
    accent_2: str
    accent_ink: str
    accent_text: str
    accent_wash: str
    accent_line: str
    accent_ring: str
    ok: str
    ok_wash: str
    err: str
    err_wash: str
    info: str
    info_wash: str
    warn: str
    warn_wash: str
    plan: str
    plan_wash: str
    think: str
    think_wash: str
    diff_add: str
    diff_add_hl: str
    diff_del: str
    diff_del_hl: str
    scrim: str
    selection: str
    find_mark: str  # a find match that is not the current one (app.css ``.find-hit``)
    popover: str  # the client's floating material (app.css ``.popover``, ``.find-bar``)
    switch_off: str  # the switch's off track, laid on the canvas
    glass: str
    glass_2: str
    edge_hi: str
    cm_comment: str
    cm_keyword: str
    cm_string: str
    cm_number: str
    cm_function: str
    cm_type: str
    cm_property: str
    cm_tag: str
    cm_regex: str
    cm_punct: str
    ansi_black: str
    ansi_red: str
    ansi_green: str
    ansi_yellow: str
    ansi_blue: str
    ansi_magenta: str
    ansi_cyan: str
    ansi_white: str
    ansi_bright_black: str
    ansi_bright_red: str
    ansi_bright_green: str
    ansi_bright_yellow: str
    ansi_bright_blue: str
    ansi_bright_magenta: str
    ansi_bright_cyan: str
    ansi_bright_white: str

    def color(self, name: str) -> QColor:
        """A token as a QColor (``rgba()`` strings included); ``"a/b"`` is token a laid over token b,
        as ``resolve`` reads it (a wash on an inset well)."""
        if "/" in name:
            c = resolve(name, self)
            if c is not None:
                return c
        return qcolor(getattr(self, name))

    def ansi(self, var: str) -> Optional[str]:
        """``var(--ansi-bright-red)`` (as lib/ansi.py emits) → the colour string, else None."""
        if var.startswith("var(--ansi-") and var.endswith(")"):
            return getattr(self, "ansi_" + var[len("var(--ansi-") : -1].replace("-", "_"), None)
        return None


