            ),
            Cmd("refresh", "Reload session list", "refresh-cw", "Actions", lambda: s.refresh_sessions(True)),
            Cmd(
                "settings",
                "Settings",
                "settings",
                "Actions",
                lambda: s.set_dialog("settings", True),
                "",
                K["settings"].keys,
            ),
            Cmd(
                "keys",
                "Keyboard shortcuts",
                "keyboard",
