        cl.setContentsMargins(0, 0, 0, 0)
        cl.setSpacing(3)
        for p in keys.split(" "):
            if p in _WORDS or (p == "/" and " / " in keys):
                w = QLabel(p)
                theme.tint(w, fg="text_3")
                w.setProperty("fs", "small")
                cl.addWidget(w)
            else:
                cl.addWidget(Keys(p))
        lay.addWidget(caps)


