        )
        self.lay.addWidget(switch_line(self.learn, "the rest learn from its summary"))

    def go_on(self) -> None:
        self.cont.setEnabled(False)
        store.call("dispatch.continue", {"id": self.job.get("id")}).catch(lambda _e: self.cont.setEnabled(True))
