    # ---- data
    def load(self) -> None:
        if not store.connected:
            return

        def items(r: Any) -> None:
            self.items = (
                [i for i in ((r or {}).get("items") or []) if isinstance(i, dict)] if isinstance(r, dict) else []
            )
