        self.run_cards = []
        if self.filter:
            name = next((str(s.get("name")) for s in scheds or [] if s.get("id") == self.filter), "one schedule")
            chip = Box(bg="fill_1/canvas", radius=15)
            cl = QHBoxLayout(chip)
            cl.setContentsMargins(12, 4, 6, 4)
            cl.setSpacing(6)
            lb = QLabel(f"Showing runs of <b>{name}</b>")
