export PILCROW_DIR="$DIR" PILCROW_NODE="$NODE"
ARGS=()
for a in "${PASS[@]+"${PASS[@]}"}"; do ARGS+=("$a"); done
[ "$BACKEND" = qt ] && ARGS+=(--qt)
if [ -t 1 ]; then
  exec "$PY" "$HOST_DIR/pilcrow-host.py" "${ARGS[@]+"${ARGS[@]}"}"
else
  nohup "$PY" "$HOST_DIR/pilcrow-host.py" "${ARGS[@]+"${ARGS[@]}"}" >>"$STATE_DIR/host.log" 2>&1 &
fi
