export function bundledPath() {
  const plat = process.platform;
  const arch = process.arch;
  const names = [`@anthropic-ai/claude-agent-sdk-${plat}-${arch}${plat === 'linux' && isMusl() ? '-musl' : ''}`, `@anthropic-ai/claude-agent-sdk-${plat}-${arch}`];
