  }
  function end() {
    if (!started) return;
    started = false;
    bus.off('state', onState);
    bus.off('msgs', onMsgs);
    bus.off('permission', onPermission);
    bus.off('permission-resolved', onPermissionResolved);
    for (const t of timers.values()) clearTimeout(t);
    timers.clear();
    for (const t of backoffTimers.values()) clearTimeout(t);
    backoffTimers.clear();
    clearTimeout(flushTimer);
    flushTimer = null;
    saver?.flush(); // what changed since the last save
  }

  return {
    events,
    scan,
    list,
    get,
    save,
    remove,
    plan,
    start,
    continue: continueJob,
    pause,
    resume,
    stop,
    retry,
    skip,
    allow,
    review,
    finish,
    exportMarkdown,
    inboxItem,
    playbooks,
    savePlaybook,
    removePlaybook,
    startFromPlaybook,
    pump,
    flush,
    summary,
    begin,
    end,
    _data: data,
  };
}
