    for (const h of f.hunks) {
      n += h.lines.length;
      for (const l of h.lines) b += l.s.length;
    }
    if (lines + n > DIFF_BUDGET_LINES || bytes + b > DIFF_BUDGET_BYTES) {
      f.hunks = [];
      f.truncated = true;
      cut++;
