  const steps = cache.get(sid) || readJson(stepsFile(cwd, sid), []);
  cache.delete(sid);
  cache.set(sid, steps);
  if (cache.size > MAX_CACHED) cache.delete(cache.keys().next().value);
  return steps;
}

