async function statsBetween(cwd, from, to) {
  const [ns, st] = await Promise.all([sg(cwd, ['diff-tree', '-r', '--numstat', from, to]), sg(cwd, ['diff-tree', '-r', '--name-status', from, to])]);
  const status = new Map();
