    if (suggest.onKey(e)) return;
    if (e.key === 'Tab' && e.shiftKey) {
      e.preventDefault();
      cycleMode();
      return;
    }
    if (e.key === 'Tab' && !text && rtSuggestion) {
      e.preventDefault();
      setText(rtSuggestion);
      return;
    }
    const isEnter = e.key === 'Enter' && !e.nativeEvent.isComposing;
    if (isEnter && busy && (e.metaKey || e.ctrlKey) && e.shiftKey) {
