      e.preventDefault();
      submit(true);
      return;
    }
    if (isEnter && ((sendWithEnter && !e.shiftKey && !e.metaKey && !e.ctrlKey && !e.altKey) || (!sendWithEnter && (e.metaKey || e.ctrlKey) && !e.shiftKey))) {
      e.preventDefault();
      submit();
      return;
