    case 'ruby':
      return legacy(() => import('@codemirror/legacy-modes/mode/ruby'), 'ruby');
    case 'r':
      return legacy(() => import('@codemirror/legacy-modes/mode/r'), 'r');
    case 'swift':
      return legacy(() => import('@codemirror/legacy-modes/mode/swift'), 'swift');
    case 'kotlin':
      return legacy(() => import('@codemirror/legacy-modes/mode/clike'), 'kotlin');
    case 'csharp':
      return legacy(() => import('@codemirror/legacy-modes/mode/clike'), 'csharp');
    case 'scala':
      return legacy(() => import('@codemirror/legacy-modes/mode/clike'), 'scala');
    case 'diff':
      return legacy(() => import('@codemirror/legacy-modes/mode/diff'), 'diff');
    case 'powershell':
      return legacy(() => import('@codemirror/legacy-modes/mode/powershell'), 'powerShell');
    case 'proto':
      return legacy(() => import('@codemirror/legacy-modes/mode/protobuf'), 'protobuf');
    case 'haskell':
      return legacy(() => import('@codemirror/legacy-modes/mode/haskell'), 'haskell');
    case 'julia':
      return legacy(() => import('@codemirror/legacy-modes/mode/julia'), 'julia');
    case 'fortran-free-form':
    case 'fortran-fixed-form':
      return legacy(() => import('@codemirror/legacy-modes/mode/fortran'), 'fortran');
    case 'matlab':
      return legacy(() => import('@codemirror/legacy-modes/mode/octave'), 'octave');
    default:
      return null;
  }
}

export function Editor({ path, doc, onChange, onSave, jump }: { path: string; doc: string; onChange: (text: string) => void; onSave: () => void; jump?: { line?: number } | null }) {
  const host = useRef<HTMLDivElement>(null);
  const view = useRef<EditorView | null>(null);
  const langComp = useRef(new Compartment());
  // The editor is made once per file: it starts from the document of that moment and calls the latest handlers.
  const initial = useEvent(() => doc);
  const change = useEvent(onChange);
  const save = useEvent(onSave);

  useEffect(() => {
    const parent = host.current;
    if (!parent) return;
    const state = EditorState.create({
      doc: initial(),
      extensions: [
        lineNumbers(),
        foldGutter(),
        highlightSpecialChars(),
        history(),
        drawSelection(),
        dropCursor(),
        rectangularSelection(),
        indentOnInput(),
        bracketMatching(),
        closeBrackets(),
        highlightActiveLine(),
        highlightActiveLineGutter(),
        highlightSelectionMatches(),
        search({ top: true }),
        indentUnit.of('  '),
        syntaxHighlighting(style),
        theme,
        EditorView.contentAttributes.of({ 'aria-label': basename(path) }), // the text box a screen reader names by its file
        langComp.current.of([]),
        keymap.of([{ key: 'Mod-s', preventDefault: true, run: () => (save(), true) }, ...closeBracketsKeymap, ...defaultKeymap, ...searchKeymap, ...historyKeymap, ...foldKeymap, indentWithTab]),
        EditorView.updateListener.of((u) => {
          if (u.docChanged) change(u.state.doc.toString());
        }),
      ],
    });
    const v = new EditorView({ state, parent });
    view.current = v;
    let alive = true;
    languageFor(path).then((ext) => {
      if (alive && ext) v.dispatch({ effects: langComp.current.reconfigure(ext) });
    });
    return () => {
      alive = false;
      v.destroy();
      view.current = null;
    };
  }, [path, initial, change, save]);

  // External reloads replace the document.
  useEffect(() => {
    const v = view.current;
    if (!v) return;
    if (v.state.doc.toString() !== doc) v.dispatch({ changes: { from: 0, to: v.state.doc.length, insert: doc } });
  }, [doc]);

  useEffect(() => {
    const v = view.current;
    if (!v || !jump?.line) return;
    const ln = Math.min(Math.max(1, jump.line), v.state.doc.lines);
    const pos = v.state.doc.line(ln).from;
    v.dispatch({ selection: { anchor: pos }, effects: EditorView.scrollIntoView(pos, { y: 'center' }) });
    v.focus();
  }, [jump]);

  return <div className="editor" ref={host} />;
}
