            <SlidersHorizontal size={13} />
          </button>
        </div>
        <label className="side-search">
          <Search size={15} />
          <input aria-label="Search sessions" placeholder="Search" value={q} onChange={(e) => setQ(e.target.value)} onKeyDown={(e) => e.key === 'Escape' && setQ('')} />
          {q && (
