          <div className="wf-bar-run" style={{ width: `${(counts.running / counts.total) * 100}%` }} />
          {counts.error > 0 && <div className="wf-bar-err" style={{ width: `${(counts.error / counts.total) * 100}%` }} />}
        </div>
      )}
      <Collapse open={!collapsed}>
        {() => (
          <div className="wfd-body">
