  verb: string;
  target: string;
  mono?: boolean;
}

const short = (p: string, cwd?: string) => (p ? relPath(p, cwd) : '');

export function toolMeta(name: string, input: ToolInput | undefined | null, cwd?: string): ToolMeta {
