  pointer-events: none;
}
.tl-cursor::before {
  content: '';
  position: absolute;
  left: 50%;
  bottom: 100%;
  width: 1px;
  height: 14px;
  margin-bottom: var(--sp-1);
  background: var(--hair-3);
}
.tl-scrub-axis {
  display: flex;
  justify-content: space-between;
  padding: var(--sp-0_5) var(--sp-1) 0;
  font-size: var(--fs-tiny);
  color: var(--text-3);
}

.tl-list {
  flex: 1;
  min-height: 0;
  overflow-y: auto;
  padding: var(--sp-2_5) var(--sp-3) var(--sp-3) var(--sp-2);
}
.tl-row {
  position: relative;
}

.tl-row-btn {
