  margin: 0;
  font-size: 26px;
  font-weight: 560;
  letter-spacing: -0.024em;
  text-align: center;
}
.welcome-sub {
  margin: var(--sp-2) 0 var(--sp-6_5);
  color: var(--text-3);
  font-size: var(--fs-body);
  text-align: center;
}
.welcome-sub b {
  color: var(--text-2);
  font-weight: 550;
}
.welcome-composer {
  width: 100%;
}
.welcome-composer .composer-input {
  min-height: 74px;
}
.welcome-folders {
  display: flex;
  flex-wrap: wrap;
  justify-content: center;
  gap: var(--sp-1_5);
  margin-top: var(--sp-3_5);
}
.welcome-keys {
  display: flex;
  gap: var(--sp-5_5);
  margin-top: var(--sp-7_5);
  font-size: var(--fs-small);
  color: var(--text-3);
}
.welcome-keys span {
  display: inline-flex;
  align-items: center;
  gap: var(--sp-1);
}
.welcome .notice {
  width: 100%;
  margin-bottom: var(--sp-3_5);
}
.popover[data-placement='top'] {
  transform-origin: bottom left;
}
.popover[data-placement='bottom'] {
  transform-origin: top left;
}

/* first run without API settings */
.setup-card {
  width: 100%;
  margin: 0 0 var(--sp-4_5);
  padding: var(--sp-3_5) var(--sp-4) var(--sp-3);
  border-radius: var(--r-6);
  background: var(--card-ask);
  box-shadow: inset 0 0 0 1.5px var(--accent-ring);
  text-align: left;
}
.setup-head {
  display: flex;
  align-items: center;
  gap: var(--sp-2);
  font-size: 14px;
  font-weight: 600;
}
.setup-head svg {
  color: var(--accent-text);
}
.setup-card p {
  margin: var(--sp-1_5) 0 var(--sp-2_5);
  font-size: var(--fs-ui);
  line-height: 1.55;
  color: var(--text-2);
}
.setup-card code {
  font-family: var(--font-mono);
  font-size: 0.92em;
  padding: 0.1em 0.35em;
  border-radius: var(--r-1);
  background: var(--fill-2);
  color: var(--text);
}
.setup-snippet {
  position: relative;
  border-radius: var(--r-4);
  background: var(--inset);
}
.setup-snippet pre {
  margin: 0;
  padding: var(--sp-2_5) var(--sp-10) var(--sp-2_5) var(--sp-3);
  font-family: var(--font-mono);
  font-size: var(--fs-small);
  line-height: 1.55;
  color: var(--text-2);
  overflow-x: auto;
}
.setup-snippet .copy-btn {
  position: absolute;
  top: 6px;
  right: 6px;
}
.setup-actions {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: var(--sp-2_5);
  margin-top: var(--sp-2_5);
  font-size: var(--fs-small);
}
